// Online-only scheduling. The single-file offline build does not include this.
function createOnlineAssets(manifest) {
  const absolute = value => new URL(value, document.baseURI).href;
  const assets = new Map(manifest.assets.map(item => [absolute(item.url), { ...item, images: new Set(), fonts: new Set() }]));
  const groups = new Map(), states = new Map();
  const nativeSource = Object.getOwnPropertyDescriptor(HTMLImageElement.prototype, "src");
  let sceneLoader = async () => {}, current = null, nextTimer = 0, readyAt = 0;
  const overlay = document.getElementById("online-loading");
  const message = document.getElementById("online-load-message");
  const retry = document.getElementById("online-load-retry");

  function assignImage(image, value) {
    const asset = assets.get(absolute(value));
    if (!asset) { nativeSource.set.call(image, value); return; }
    let resolve, reject;
    const job = { image, started: false, promise: new Promise((yes, no) => { resolve = yes; reject = no; }) };
    // Deferred sources are allowed to stay unused for an entire playthrough.
    job.promise.catch(() => {});
    job.start = () => {
      if (job.started) return;
      job.started = true;
      image.addEventListener("load", () => resolve(image), { once: true });
      image.addEventListener("error", () => reject(new Error("Image could not be decoded")), { once: true });
      nativeSource.set.call(image, asset.objectURL);
    };
    asset.images.add(job);
    if (asset.objectURL) job.start();
  }
  function image() {
    const element = new Image();
    const complete = Object.getOwnPropertyDescriptor(HTMLImageElement.prototype, "complete");
    let requested = "";
    Object.defineProperties(element, {
      src: { configurable: true, get: () => requested ? absolute(requested) : nativeSource.get.call(element), set: value => { requested = String(value); assignImage(element, requested); } },
      complete: { configurable: true, get: () => requested && assets.has(absolute(requested)) && !assets.get(absolute(requested)).objectURL ? false : complete.get.call(element) },
    });
    return element;
  }
  function font(family, source, descriptors) {
    const face = new FontFace(family, source, descriptors);
    const match = /url\(["']?([^"')]+)["']?\)/.exec(source);
    const asset = match && assets.get(absolute(match[1]));
    if (!asset) return face;
    const nativeLoad = face.load.bind(face);
    let job;
    face.load = () => {
      if (!job) {
        let resolve, reject;
        job = { started: false, promise: new Promise((yes, no) => { resolve = yes; reject = no; }) };
        job.promise.catch(() => {});
        job.start = () => {
          if (job.started) return;
          job.started = true;
          nativeLoad().then(resolve, reject);
        };
        asset.fonts.add(job);
        if (asset.buffer) job.start();
      }
      return job.promise;
    };
    return face;
  }
  async function loadAsset(url, background) {
    const asset = assets.get(absolute(url));
    if (!asset) throw new Error("Unknown online asset");
    if (asset.promise) return asset.promise;
    asset.promise = (async () => {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 45000);
      try {
        const response = await fetch(asset.url, { cache: "force-cache", signal: controller.signal, priority: background ? "low" : "high" });
        if (!response.ok) throw new Error("Asset download failed");
        asset.buffer = await response.arrayBuffer();
        if (asset.kind === "image" || asset.kind === "model") {
          asset.objectURL = URL.createObjectURL(new Blob([asset.buffer], { type: asset.mime }));
        }
        for (const job of asset.images) job.start();
        for (const job of asset.fonts) job.start();
        await Promise.all([...asset.images, ...asset.fonts].map(job => job.promise));
        asset.loaded = true;
      } finally { clearTimeout(timeout); }
    })().catch(error => { asset.promise = null; throw error; });
    return asset.promise;
  }
  async function prepare(id, background = false) {
    id = String(id);
    if (groups.has(id)) return groups.get(id);
    const group = manifest.groups[id];
    if (!group) throw new Error("Unknown game chapter");
    states.set(id, "loading");
    const promise = (async () => {
      await Promise.all(group.map(url => loadAsset(url, background)));
      await sceneLoader(id);
      states.set(id, "ready");
    })().catch(error => { groups.delete(id); states.set(id, "retry"); throw error; });
    groups.set(id, promise);
    return promise;
  }
  async function requireGroup(id) {
    if (states.get(String(id)) === "ready") return prepare(id);
    overlay.hidden = false;
    message.hidden = true; retry.hidden = true;
    try {
      for (;;) {
        try { return await prepare(id); }
        catch {
          message.hidden = false; retry.hidden = false;
          await new Promise(resolve => retry.addEventListener("click", resolve, { once: true }));
          message.hidden = true; retry.hidden = true;
        }
      }
    } finally { overlay.hidden = true; }
  }
  function didEnter(id) {
    current = String(id);
    if (!readyAt) readyAt = performance.now();
    clearTimeout(nextTimer);
    const index = manifest.order.indexOf(current), next = manifest.order[index + 1];
    if (!next) return;
    // The current chapter becomes interactive before any next-chapter traffic.
    nextTimer = setTimeout(() => { prepare(next, true).catch(() => {}); }, 1200);
  }
  return {
    image, font, assignImage, prepare, requireGroup, didEnter,
    setSceneLoader(loader) { sceneLoader = loader; },
    buffer(url) { return assets.get(absolute(url))?.buffer; },
    objectURL(url) { return assets.get(absolute(url))?.objectURL; },
    snapshot() { return { current, readyAt, groups: Object.fromEntries(states), loaded: [...assets.values()].filter(asset => asset.loaded).map(asset => asset.url) }; },
  };
}

