window.addEventListener("keydown", event => {
  if (!event.shiftKey || event.altKey || event.metaKey || event.ctrlKey || event.isComposing) return;
  // Physical digit codes still identify 1–8 when Shift produces !, @, #, etc.
  const match = /^(?:Digit|Numpad)([1-8])$/.exec(event.code) || /^([1-8])$/.exec(event.key);
  if (!match || event.target instanceof Element && event.target.closest("input, textarea, select, [contenteditable]:not([contenteditable='false'])")) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (!event.repeat) window.__level.debugJumpTo(Number(match[1]));
}, { capture: true });

const onlineAudioPromises = new Map();
async function loadOnlineAudio(key) {
  if ($o[key]) return;
  if (onlineAudioPromises.has(key)) return onlineAudioPromises.get(key);
  ob();
  const promise = se.decodeAudioData(wutiAssets.buffer(rb[key]).slice(0)).then(buffer => {
    if (ab.has(key)) {
      let peak = 0;
      for (let channel = 0; channel < buffer.numberOfChannels; channel++) for (const sample of buffer.getChannelData(channel)) peak = Math.max(peak, Math.abs(sample));
      if (peak > .001) for (let channel = 0; channel < buffer.numberOfChannels; channel++) {
        const samples = buffer.getChannelData(channel), scale = .5 / peak;
        for (let i = 0; i < samples.length; i++) samples[i] *= scale;
      }
    }
    $o[key] = buffer;
  }).catch(error => { onlineAudioPromises.delete(key); throw error; });
  onlineAudioPromises.set(key, promise);
  return promise;
}
